class Store:
    def __init__(self):
        self._d = {}

    def put(self, key, value):
        self._d[key] = value

    def get(self, key, default=None):
        return self._d.get(key, default)

    def delete(self, key):
        self._d.pop(key, None)

    def keys(self):
        return list(self._d)

    def __len__(self):
        return len(self._d)

