import json, os, sys

PATH = os.environ.get('TASKS_FILE') or os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tasks.json')


def load():
    if not os.path.exists(PATH):
        return []
    return json.load(open(PATH))


def save(ts):
    json.dump(ts, open(PATH, 'w'))


def cmd_list(args):
    for i, t in enumerate(load()):
        print(f"{i+1}. [{'x' if t['done'] else ' '}] {t['title']}")


def cmd_add(args):
    ts = load()
    ts.append({'title': ' '.join(args), 'done': False})
    save(ts)
    print(f'added {len(ts)}')


def cmd_done(args):
    ts = load()
    n = int(args[0])
    ts[n-1]['done'] = True
    save(ts)
    print(f'done {n}')


if __name__ == '__main__':
    cmd, rest = sys.argv[1], sys.argv[2:]
    {'list': cmd_list, 'add': cmd_add, 'done': cmd_done}[cmd](rest)

