from .rates import OVERTIME, BONUS, TAX, ALLOWANCE


def payslip(hours, rate, bonus=False):
    base = round(min(hours, 40) * rate, 2)
    over = round(max(0, hours - 40) * rate * OVERTIME, 2)
    gross = base + over
    if bonus:
        gross += gross * BONUS
    taxable = gross - ALLOWANCE
    tax = taxable * TAX
    return {'gross': round(gross, 2), 'tax': round(tax, 2), 'net': round(gross - tax, 2)}

