class HttpError(Exception):
    pass

PAGES = {'/a': 'alpha', '/b': 'beta', '/c': 'gamma'}


def get(url):
    if url not in PAGES:
        raise HttpError(f'404 {url}')
    return PAGES[url]


def fetch(url, callback):
    try:
        callback(None, get(url))
    except HttpError as e:
        callback(e, None)

