def norm(email):
    e = email.strip().lower()
    local, _, domain = e.partition('@')
    if domain == 'gmail.com':
        local = local.replace('.', '')
    return local + '@' + domain


def find_duplicates(records):
    groups = []
    seen = set()
    for i, (rid, email) in enumerate(records):
        if rid in seen:
            continue
        g = [rid]
        for rid2, email2 in records[i + 1:]:
            if norm(email2) == norm(email):
                g.append(rid2)
                seen.add(rid2)
        if len(g) > 1:
            groups.append(sorted(g))
    return sorted(groups, key=lambda g: g[0])

